import collections
from itertools import zip_longest
from random import choices

def task_func(l1, l2, K=10):
    # Use a sentinel object to distinguish actual None values in the lists from the padding added by zip_longest
    sentinel = object()
    combined = [
        x for pair in zip_longest(l1, l2, fillvalue=sentinel) 
        for x in pair if x is not sentinel
    ]

    # Handle the edge case where both lists are empty to avoid IndexError from choices()
    if not combined:
        return collections.Counter()

    sample = choices(combined, k=K)
    return collections.Counter(sample)

